"""Small, dependency-free renderer for bounded report-configured microsites."""
from __future__ import annotations

from html import escape
import json
from pathlib import Path
from typing import Any, Mapping

CHART_KINDS = frozenset({"timeline", "contribution", "comparison", "heatmap", "scatter", "scenario", "coefficient", "dumbbell", "evidence-table"})


def _json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def validate_report(config: Mapping[str, Any]) -> None:
    divisions = config.get("divisions", [])
    if not divisions or any(not d.get("pages") for d in divisions):
        raise ValueError("A report requires configured divisions and pages")
    ids: set[str] = set()
    for division in divisions:
        for page in division["pages"]:
            route = f"{division['id']}/{page['id']}"
            if route in ids:
                raise ValueError(f"Duplicate route: {route}")
            ids.add(route)
            for chart in page.get("charts", []):
                if chart.get("kind") not in CHART_KINDS:
                    raise ValueError(f"Unsupported chart kind: {chart.get('kind')}")
    if len(config.get("controls", [])) > 6:
        raise ValueError("Reports may declare at most six bounded controls")


def render_report(config: Mapping[str, Any]) -> str:
    """Render structured report content as one self-contained HTML document."""
    validate_report(config)
    title = escape(str(config["title"]))
    return f'''<!doctype html>
<html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="icon" href="data:,"><style>{CSS}</style></head>
<body><a class="skip" href="#content">Skip to report content</a>
<header class="top"><div class="brand"><i>BF</i><span><b>BriefForge</b><small>Interactive research</small></span></div><nav id="divnav" aria-label="Report divisions"></nav><div class="edition">RESEARCH<br><b>MICROSITE</b></div></header>
<header class="mobile"><b id="crumb">{title}</b><button id="menu" aria-expanded="false" aria-controls="drawer">☰</button></header>
<div class="controls" id="controls" aria-label="Report controls"></div>
<aside class="side"><div id="divisionLabel"></div><nav id="pagenav" aria-label="Division pages"></nav><div class="source-note" id="sourceNote"></div></aside>
<div class="drawer mobile-drawer" id="drawer"><h2>Report index</h2><div id="mobileNav"></div><h2>Controls</h2><div id="mobileControls"></div></div>
<main id="content"><div class="warning" id="warning"></div><div class="canvas" id="canvas"></div></main>
<div class="tooltip" id="tooltip" role="status" aria-live="polite"></div>
<script id="report-config" type="application/json">{_json(config)}</script><script>{JS}</script></body></html>'''


def write_report(config: Mapping[str, Any], destination: str | Path) -> Path:
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(render_report(config), encoding="utf-8")
    return destination


